#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$SCRIPT_DIR"
if [[ ! -d "$REPO_ROOT/.agent-rules" && -d "$SCRIPT_DIR/../.agent-rules" ]]; then
	REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
fi
RULES_ROOT="$REPO_ROOT/.agent-rules"
ENTRYPOINTS=(AGENTS.md CLAUDE.md GEMINI.md)

for source_file in base.md framework.md; do
	if [[ ! -f "$RULES_ROOT/$source_file" ]]; then
		echo "MISSING  .agent-rules/$source_file" >&2
		exit 1
	fi
done

render_document() {
	cat <<'EOF'
<!-- GENERATED BY agent-rules. Do not edit this file directly. -->

EOF
	cat "$RULES_ROOT/base.md"
	printf '\n'
	cat "$RULES_ROOT/framework.md"
	if [[ -f "$RULES_ROOT/project.md" ]]; then
		printf '\n'
		cat "$RULES_ROOT/project.md"
	fi
}

temp_dir="$(mktemp -d "${TMPDIR:-/tmp}/agent-rules-local.XXXXXX")"
trap 'rm -rf "$temp_dir"' EXIT
render_document > "$temp_dir/candidate"

for entrypoint in "${ENTRYPOINTS[@]}"; do
	target_file="$REPO_ROOT/$entrypoint"
	cp "$temp_dir/candidate" "$target_file"
done

echo "SYNCED   agent entrypoints"
